mapper.select:
SELECT event_id, module_name, priority, event_label, event_name, report_terminal,
       trigger_timing, metric_codes, version_no, status, create_by, create_time,
       update_by, update_time, remark
FROM bi_tracking_event

    AND module_name = #{moduleName}
    AND report_terminal = #{reportTerminal}
    AND status = #{status}

        AND (event_name LIKE CONCAT('%', #{keyword}, '%')
            OR event_label LIKE CONCAT('%', #{keyword}, '%'))


ORDER BY FIELD(priority, 'P0', 'P1', 'P2', '--'), event_id

SELECT COUNT(1) FROM bi_tracking_event
WHERE event_name = #{eventName}
AND event_id != #{eventId}

mapper.update:
UPDATE bi_tracking_event SET module_name = #{moduleName}, priority = #{priority},
    event_label = #{eventLabel}, event_name = #{eventName},
    report_terminal = #{reportTerminal}, trigger_timing = #{triggerTiming},
    metric_codes = #{metricCodes}, version_no = #{versionNo}, status = #{status},
    update_by = #{updateBy}, update_time = SYSDATE(), remark = #{remark}
WHERE event_id = #{eventId}

